```turtle
@prefix ea: <http://example.org/onto/assessment#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/assessment>
    a owl:Ontology ;
    rdfs:label "Educational Assessment Ontology"@en ;
    rdfs:comment "An OWL DL ontology modeling educational assessment, measurement, psychometric properties, item types, scoring, and feedback strictly as described in the provided corpus."@en .

#################################################################
#    Top-Level Classes
#################################################################

ea:EducationalActivity
    a owl:Class ;
    rdfs:label "Educational Activity"@en ;
    rdfs:comment "An activity in an educational context."@en .

ea:Assessment
    a owl:Class ;
    rdfs:subClassOf ea:EducationalActivity ;
    rdfs:label "Assessment"@en ;
    skos:altLabel "Educational Assessment"@en , "Educational Evaluation"@en ;
    rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude, and beliefs to refine programs and improve student learning."@en .

ea:AssessmentItem
    a owl:Class ;
    rdfs:label "Assessment Item"@en ;
    skos:altLabel "Question"@en , "Test Item"@en ;
    rdfs:comment "A unit of an assessment or test, such as a question, problem, or prompt."@en .

ea:ItemComponent
    a owl:Class ;
    rdfs:label "Item Component"@en ;
    rdfs:comment "A structural part of an assessment item."@en .

ea:AssessmentArtifact
    a owl:Class ;
    rdfs:label "Assessment Artifact"@en ;
    rdfs:comment "An instrument, guide, scoring tool, or evidentiary product used or produced in assessment."@en .

ea:MeasurementProperty
    a owl:Class ;
    rdfs:label "Measurement Property"@en ;
    rdfs:comment "A quality attribute of an educational assessment or measurement."@en .

ea:Feedback
    a owl:Class ;
    rdfs:label "Feedback"@en ;
    rdfs:comment "Information provided to students or teachers regarding performance or understanding."@en .

ea:ScoreInterpretation
    a owl:Class ;
    rdfs:label "Score Interpretation"@en ;
    rdfs:comment "The method or framework used to interpret test scores."@en .

ea:EvaluationStandard
    a owl:Class ;
    rdfs:label "Evaluation Standard"@en ;
    rdfs:comment "Guidelines or criteria published to promote evaluations that are appropriate, useful, feasible, and accurate."@en .

ea:Stakeholder
    a owl:Class ;
    rdfs:label "Stakeholder"@en ;
    rdfs:comment "An individual or agent involved in educational assessment."@en .

#################################################################
#    Axis Reification: Value Partitions & Functional Properties
#################################################################

# --- Axis: Purpose / Function ---

ea:PurposeCategory
    a owl:Class ;
    rdfs:label "Purpose Category"@en ;
    owl:disjointUnionOf (
        ea:FormativePurpose
        ea:SummativePurpose
        ea:PlacementPurpose
        ea:DiagnosticPurpose
        ea:InterimPurpose
        ea:ScreeningPurpose
        ea:ForwardLookingPurpose
    ) .

ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory ; rdfs:label "Formative Purpose"@en .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory ; rdfs:label "Summative Purpose"@en .
ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory ; rdfs:label "Placement Purpose"@en .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory ; rdfs:label "Diagnostic Purpose"@en .
ea:InterimPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory ; rdfs:label "Interim Purpose"@en .
ea:ScreeningPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory ; rdfs:label "Screening Purpose"@en .
ea:ForwardLookingPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory ; rdfs:label "Forward-Looking Purpose"@en .

ea:hasPurpose
    a owl:ObjectProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:PurposeCategory ;
    rdfs:label "has purpose"@en .

# --- Axis: Referencing Framework ---

ea:ReferencingFramework
    a owl:Class ;
    rdfs:label "Referencing Framework"@en ;
    owl:disjointUnionOf (
        ea:CriterionReferencing
        ea:NormReferencing
        ea:IpsativeReferencing
    ) .

ea:CriterionReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingFramework ; rdfs:label "Criterion Referencing"@en .
ea:NormReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingFramework ; rdfs:label "Norm Referencing"@en .
ea:IpsativeReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingFramework ; rdfs:label "Ipsative Referencing"@en .

ea:hasReferencingFramework
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:ReferencingFramework ;
    rdfs:label "has referencing framework"@en .

# --- Axis: Scoring Objectivity ---

ea:ObjectivityCategory
    a owl:Class ;
    rdfs:label "Objectivity Category"@en ;
    owl:disjointUnionOf (
        ea:ObjectiveScoring
        ea:SubjectiveScoring
    ) .

ea:ObjectiveScoring a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory ; rdfs:label "Objective Scoring"@en .
ea:SubjectiveScoring a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory ; rdfs:label "Subjective Scoring"@en .

ea:hasObjectivityCategory
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain [ a owl:Class ; owl:unionOf ( ea:Assessment ea:AssessmentItem ) ] ;
    rdfs:range ea:ObjectivityCategory ;
    rdfs:label "has objectivity category"@en .

# --- Axis: Formality ---

ea:FormalityCategory
    a owl:Class ;
    rdfs:label "Formality Category"@en ;
    owl:disjointUnionOf (
        ea:FormalFormality
        ea:InformalFormality
    ) .

ea:FormalFormality a owl:Class ; rdfs:subClassOf ea:FormalityCategory ; rdfs:label "Formal Formality"@en .
ea:InformalFormality a owl:Class ; rdfs:subClassOf ea:FormalityCategory ; rdfs:label "Informal Formality"@en .

ea:hasFormalityCategory
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:FormalityCategory ;
    rdfs:label "has formality category"@en .

# --- Axis: Agency / Origin (Internal vs External) ---

ea:AgencyCategory
    a owl:Class ;
    rdfs:label "Agency Category"@en ;
    owl:disjointUnionOf (
        ea:InternalAgency
        ea:ExternalAgency
    ) .

ea:InternalAgency a owl:Class ; rdfs:subClassOf ea:AgencyCategory ; rdfs:label "Internal Agency"@en .
ea:ExternalAgency a owl:Class ; rdfs:subClassOf ea:AgencyCategory ; rdfs:label "External Agency"@en .

ea:hasAgencyCategory
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:AgencyCategory ;
    rdfs:label "has agency category"@en .

# --- Axis: Standardization ---

ea:StandardizationCategory
    a owl:Class ;
    rdfs:label "Standardization Category"@en ;
    owl:disjointUnionOf (
        ea:StandardizedFormat
        ea:NonStandardizedFormat
    ) .

ea:StandardizedFormat a owl:Class ; rdfs:subClassOf ea:StandardizationCategory ; rdfs:label "Standardized Format"@en .
ea:NonStandardizedFormat a owl:Class ; rdfs:subClassOf ea:StandardizationCategory ; rdfs:label "Non-Standardized Format"@en .

ea:hasStandardizationCategory
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:StandardizationCategory ;
    rdfs:label "has standardization category"@en .

# --- Axis: Stakes ---

ea:StakesCategory
    a owl:Class ;
    rdfs:label "Stakes Category"@en ;
    owl:disjointUnionOf (
        ea:HighStakes
        ea:LowStakes
    ) .

ea:HighStakes a owl:Class ; rdfs:subClassOf ea:StakesCategory ; rdfs:label "High Stakes"@en .
ea:LowStakes a owl:Class ; rdfs:subClassOf ea:StakesCategory ; rdfs:label "Low Stakes"@en .

ea:hasStakesCategory
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:StakesCategory ;
    rdfs:label "has stakes category"@en .

# --- Axis: Delivery Mode ---

ea:DeliveryMode
    a owl:Class ;
    rdfs:label "Delivery Mode"@en ;
    owl:disjointUnionOf (
        ea:WrittenMode
        ea:OralMode
        ea:PracticalMode
    ) .

ea:WrittenMode a owl:Class ; rdfs:subClassOf ea:DeliveryMode ; rdfs:label "Written Mode"@en .
ea:OralMode a owl:Class ; rdfs:subClassOf ea:DeliveryMode ; rdfs:label "Oral Mode"@en .
ea:PracticalMode a owl:Class ; rdfs:subClassOf ea:DeliveryMode ; rdfs:label "Practical Mode"@en .

ea:hasDeliveryMode
    a owl:ObjectProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:DeliveryMode ;
    rdfs:label "has delivery mode"@en .

# --- Axis: Scoring Approach ---

ea:ScoringApproach
    a owl:Class ;
    rdfs:label "Scoring Approach"@en ;
    owl:disjointUnionOf (
        ea:HolisticScoringApproach
        ea:AnalyticScoringApproach
        ea:TraitInformedScoringApproach
    ) .

ea:HolisticScoringApproach a owl:Class ; rdfs:subClassOf ea:ScoringApproach ; rdfs:label "Holistic Scoring Approach"@en .
ea:AnalyticScoringApproach a owl:Class ; rdfs:subClassOf ea:ScoringApproach ; rdfs:label "Analytic Scoring Approach"@en .
ea:TraitInformedScoringApproach a owl:Class ; rdfs:subClassOf ea:ScoringApproach ; rdfs:label "Trait-Informed Scoring Approach"@en .

ea:hasScoringApproach
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain [ a owl:Class ; owl:unionOf ( ea:Assessment ea:Rubric ) ] ;
    rdfs:range ea:ScoringApproach ;
    rdfs:label "has scoring approach"@en .

#################################################################
#    Assessment Kinds: Bridge Definitions via Axes
#################################################################

ea:FormativeAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ]
        )
    ] ;
    rdfs:label "Formative Assessment"@en ;
    skos:altLabel "Assessment for Learning"@en , "Classroom Assessment"@en , "Educative Assessment"@en ;
    rdfs:comment "Conducted during instruction to monitor student learning and modify teaching and learning activities; typically low-stakes and provides ongoing qualitative feedback."@en .

ea:SummativeAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ]
        )
    ] ;
    rdfs:label "Summative Assessment"@en ;
    skos:altLabel "Assessment of Learning"@en , "Summative Evaluation"@en ;
    rdfs:comment "Administered at the conclusion of an instructional period to evaluate student learning against standards; typically graded and often high-stakes."@en .

ea:PlacementAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ]
        )
    ] ;
    rdfs:label "Placement Assessment"@en ;
    skos:altLabel "Initial Assessment"@en , "Pre-Assessment"@en , "Threshold Knowledge Test"@en ;
    rdfs:comment "Conducted before instruction to establish a baseline and place students at the most appropriate point in an instructional sequence."@en .

ea:DiagnosticAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ]
        )
    ] ;
    rdfs:label "Diagnostic Assessment"@en ;
    skos:altLabel "Diagnostic Testing"@en ;
    rdfs:comment "Corpus tension: Listed as a coordinate alternative to placement, formative, and summative assessments in one section, but explicitly characterized as a common form or subset of formative assessment in other sections. Both claims are modeled here."@en .

# Subordination of Diagnostic Assessment under Formative Assessment as stated in the corpus:
ea:DiagnosticAssessment rdfs:subClassOf ea:FormativeAssessment .

ea:InterimAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:InterimPurpose ]
        )
    ] ;
    rdfs:label "Interim Assessment"@en ;
    skos:altLabel "Benchmark Assessment"@en ;
    rdfs:comment "Periodic assessment to monitor student progress toward standards; debated whether it functions as formative or summative."@en .

ea:ScreeningAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:ScreeningPurpose ]
        )
    ] ;
    rdfs:label "Screening Assessment"@en ;
    rdfs:comment "Used to determine readiness for a program or identify needs for specialized assistance."@en .

ea:ForwardLookingAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:ForwardLookingPurpose ]
        )
    ] ;
    rdfs:label "Forward-Looking Assessment"@en ;
    rdfs:comment "Asks test takers to consider themselves in hypothetical future situations."@en .

# Referencing-based Bridges

ea:CriterionReferencedAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasReferencingFramework ; owl:someValuesFrom ea:CriterionReferencing ]
        )
    ] ;
    rdfs:label "Criterion-Referenced Assessment"@en ;
    skos:altLabel "Criterion-Referenced Test"@en , "Standards-Based Assessment"@en ;
    rdfs:comment "Measures student performance against a fixed, predetermined set of criteria or learning standards."@en .

ea:NormReferencedAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasReferencingFramework ; owl:someValuesFrom ea:NormReferencing ]
        )
    ] ;
    rdfs:label "Norm-Referenced Assessment"@en ;
    skos:altLabel "Norm-Referenced Test"@en , "Normative Assessment"@en ;
    rdfs:comment "Compares and ranks test takers in relation to one another or against a norming group on a curve."@en .

ea:IpsativeAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasReferencingFramework ; owl:someValuesFrom ea:IpsativeReferencing ]
        )
    ] ;
    rdfs:label "Ipsative Assessment"@en ;
    rdfs:comment "Assesses present performance against the previous performance of the individual test taker."@en .

# Objectivity-based Bridges

ea:ObjectiveAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasObjectivityCategory ; owl:someValuesFrom ea:ObjectiveScoring ]
        )
    ] ;
    rdfs:label "Objective Assessment"@en ;
    rdfs:comment "Assessment consisting of questioning that has a single correct answer."@en .

ea:SubjectiveAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasObjectivityCategory ; owl:someValuesFrom ea:SubjectiveScoring ]
        )
    ] ;
    rdfs:label "Subjective Assessment"@en ;
    rdfs:comment "Assessment consisting of questioning that may have more than one correct answer or way of expressing it."@en .

# Formality-based Bridges

ea:FormalAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasFormalityCategory ; owl:someValuesFrom ea:FormalFormality ]
        )
    ] ;
    rdfs:label "Formal Assessment"@en ;
    rdfs:comment "Assessment typically implying a written document, numerical score, or grade contributing to student evaluation."@en .

ea:InformalAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasFormalityCategory ; owl:someValuesFrom ea:InformalFormality ]
        )
    ] ;
    rdfs:label "Informal Assessment"@en ;
    rdfs:comment "Casual assessment that does not contribute to a final course grade, such as observations or checklists."@en .

# Agency-based Bridges

ea:InternalAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasAgencyCategory ; owl:someValuesFrom ea:InternalAgency ]
        )
    ] ;
    rdfs:label "Internal Assessment"@en ;
    rdfs:comment "Assessment set and marked by the school or internal teachers."@en .

ea:ExternalAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasAgencyCategory ; owl:someValuesFrom ea:ExternalAgency ]
        )
    ] ;
    rdfs:label "External Assessment"@en ;
    rdfs:comment "Assessment set by an external governing body and marked by external or unbiased personnel."@en .

# Standardization-based Bridges

ea:StandardizedTest
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasStandardizationCategory ; owl:someValuesFrom ea:StandardizedFormat ]
        )
    ] ;
    rdfs:label "Standardized Test"@en ;
    skos:altLabel "Standardized Assessment"@en ;
    rdfs:comment "A test administered and scored in a consistent, uniform, predetermined manner."@en .

ea:NonStandardizedTest
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasStandardizationCategory ; owl:someValuesFrom ea:NonStandardizedFormat ]
        )
    ] ;
    rdfs:label "Non-Standardized Test"@en ;
    skos:altLabel "Non-Standardized Assessment"@en ;
    rdfs:comment "A test where different conditions, questions, or evaluations are used across test takers."@en .

# Stakes-based Bridges

ea:HighStakesTest
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasStakesCategory ; owl:someValuesFrom ea:HighStakes ]
        )
    ] ;
    rdfs:label "High-Stakes Test"@en ;
    skos:altLabel "High-Stakes Assessment"@en ;
    rdfs:comment "An assessment whose results have important consequences, such as graduation, licensure, or accountability."@en .

ea:LowStakesTest
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasStakesCategory ; owl:someValuesFrom ea:LowStakes ]
        )
    ] ;
    rdfs:label "Low-Stakes Test"@en ;
    skos:altLabel "Low-Stakes Assessment"@en ;
    rdfs:comment "An assessment carrying no significant or public consequences."@en .

#################################################################
#    Specific Assessment Formats and Instruments
#################################################################

ea:Test
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Test"@en ;
    skos:altLabel "Examination"@en ;
    rdfs:comment "An assessment intended to measure knowledge, skill, aptitude, physical fitness, or standing."@en .

ea:CompetitiveExamination
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Test
            ea:NormReferencedAssessment
            ea:HighStakesTest
        )
    ] ;
    rdfs:label "Competitive Examination"@en ;
    rdfs:comment "A norm-referenced, high-stakes test ranking candidates to select top rankers for limited positions."@en .

ea:ContinuousAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Continuous Assessment"@en ;
    rdfs:comment "Assessment that evaluates student progress throughout a course as an alternative to single final exams."@en .

ea:SelfAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Self-Assessment"@en ;
    skos:altLabel "Self-Evaluation"@en ;
    rdfs:comment "Assessment where learners evaluate their own work and progress."@en .

ea:PeerAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Peer Assessment"@en ;
    skos:altLabel "Peer Evaluation"@en ;
    rdfs:comment "Assessment conducted by peers of the learner."@en .

ea:PerformanceBasedAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Performance-Based Assessment"@en ;
    skos:altLabel "Performance Test"@en ;
    rdfs:comment "Requires students to perform an actual task or create a product rather than simply answering questions."@en .

ea:AuthenticAssessment
    a owl:Class ;
    rdfs:subClassOf ea:PerformanceBasedAssessment ;
    rdfs:label "Authentic Assessment"@en ;
    rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside school."@en .

ea:PortfolioBasedAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Portfolio-Based Assessment"@en ;
    rdfs:comment "Assessment based on a collection of academic work assembled over time."@en .

ea:ComplexAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Complex Assessment"@en ;
    rdfs:comment "An assessment that requires an expert examiner and a rubric, such as a final-year project thesis."@en .

ea:Quiz
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    rdfs:label "Quiz"@en ;
    rdfs:comment "A brief assessment covering a small amount of material."@en .

ea:MidtermExam
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    rdfs:label "Midterm Exam"@en ;
    rdfs:comment "An examination administered near the middle of an academic term."@en .

ea:FinalExam
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    rdfs:label "Final Exam"@en ;
    skos:altLabel "Finals"@en ;
    rdfs:comment "A culminating test of topics covered across an instructional period or entire degree."@en .

ea:WrittenTest
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Test
            [ a owl:Restriction ; owl:onProperty ea:hasDeliveryMode ; owl:someValuesFrom ea:WrittenMode ]
        )
    ] ;
    rdfs:label "Written Test"@en ;
    rdfs:comment "A test administered on paper or computer."@en .

ea:OralTest
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Test
            [ a owl:Restriction ; owl:onProperty ea:hasDeliveryMode ; owl:someValuesFrom ea:OralMode ]
        )
    ] ;
    rdfs:label "Oral Test"@en ;
    rdfs:comment "A test administered verbally."@en .

ea:PracticalTest
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    owl:equivalentClass [
        owl:intersectionOf (
            ea:Test
            [ a owl:Restriction ; owl:onProperty ea:hasDeliveryMode ; owl:someValuesFrom ea:PracticalMode ]
        )
    ] ;
    rdfs:label "Practical Test"@en ;
    rdfs:comment "A test requiring practical demonstration of skills, such as driving or a musical recital."@en .

ea:PaperBasedTest
    a owl:Class ;
    rdfs:subClassOf ea:WrittenTest ;
    rdfs:label "Paper-Based Test"@en ;
    rdfs:comment "A written test administered on paper."@en .

ea:ComputerBasedTest
    a owl:Class ;
    rdfs:subClassOf ea:WrittenTest ;
    rdfs:label "Computer-Based Test"@en ;
